[[module CSS]]

:root {

    --1-color: #800000;/* 顶端栏条的背景色以及评分栏边框颜色 */

    --2-color: #DEB887;/* 整个页面正文部分的背景色 */

    --3-color: #F5F5F5;/* 页面标题颜色以及顶端栏字的颜色 */

    --4-color: #F5F5F5;/* 文中字体颜色以及底下页面版本颜色 */

    --5-color: #8B0000;/* 登录账号的颜色与链接的颜色 */

    --6-color: #FFA500;/* 顶端副标题文字 */

    --7-color: #FFD700;/* 顶端主标题文字 */

}



#page-content div.myImageBlock {

    margin: 2em 0;

    width: 100%;

    border: solid 1px #AD90F8;

    background-color: #170438;

    box-shadow: 0 1px 6px rgba(0,0,0,0.25);

}

#page-content div.myImageBlock img {

    width: 100%;

}

#page-content div.myImageBlock div.myImageCaption {

    text-align: center;

    border-top: solid 1px #AD90F8;

}

#page-content div.myImageBlock div.myImageCaption p {

    margin: 4px 1em;

    padding: 0;

}



div#extra-div-1 {

    background: url("https://zh.minecraft.wiki/images/Crimson_Forest.png?e2ae8&format=original");

    background-size: cover;

    background-position: 50% 20%;

}



#header h1 a::before {

    content: "AREA-MC-08";

    color: var(--7-color);

}



#header h2 span::before {

    content: "热浪奔涌·火舞烬生";

    color: var(--6-color);

    filter: drop-shadow(0 0 2rem #000000);

}



#header {

    background: url("https://aceattackassassin.wikidot.com/local--files/secure-facility-dossier-area-mc-08/Area-MC-08-LOGO-Dark") 0px 60px / 7em 7em no-repeat;

    background-size: 60px 60px;

}



#login-status, #login-status a {

    color: var(--5-color);

}



[[/module]]





